import{_ as s,C as e,o,c as l,E as a,a2 as d}from"./chunks/framework.Bx6eOp9J.js";const g=JSON.parse('{"title":"同样是 0.5，为什么信任状态不能只存一个分数","description":"","frontmatter":{"title":"同样是 0.5，为什么信任状态不能只存一个分数","date":"2026-10-26","column":"industry-architecture","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"可见信任分数能否代表可恢复状态，分数信息与使用指导能否分开检验？","summary":"固定源码实验中，两种同为 0.5 的信任状态在相同反馈后更新不同。恢复估计器、展示分数和指导决策，需要分别保存和检验。","sources":["https://arxiv.org/html/2610.31971","https://github.com/amit-sarker/TASMAN/blob/7e55fdb8791dd9ec03819534649420311ab8b374/src/BRS/brs.py"],"pageClass":"runtime-v6-article","item_id":"SIG-20261026-004","lifecycle":"Published","cover":"/assets/covers/daily-2026-10-26-sig-20261026-004-2026-10-26-trust-state.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-10-26-sig-20261026-004.md","filePath":"zh/industry/2026-10-26-sig-20261026-004.md","lastUpdated":1793018684000}'),n={name:"zh/industry/2026-10-26-sig-20261026-004.md"};function c(h,t,p,u,b,m){const r=e("ArticleCover"),i=e("ArticleTableScroll");return o(),l("div",null,[a(r,{image:"/assets/covers/daily-2026-10-26-sig-20261026-004-2026-10-26-trust-state.png",kicker:"研究成果",title:"同样是 0.5，为什么信任状态不能只存一个分数",summary:"固定源码实验中，两种同为 0.5 的信任状态在相同反馈后更新不同。恢复估计器、展示分数和指导决策，需要分别保存和检验。",version:"2026-10-26",languageHref:"/en/industry/2026-10-26-sig-20261026-004",languageLabel:"English"}),a(i,{language:"zh"}),t[0]||(t[0]=d('<h1 id="同样是-0-5-为什么信任状态不能只存一个分数" tabindex="-1">同样是 0.5，为什么信任状态不能只存一个分数 <a class="header-anchor" href="#同样是-0-5-为什么信任状态不能只存一个分数" aria-label="Permalink to &quot;同样是 0.5，为什么信任状态不能只存一个分数&quot;">​</a></h1><p>两个信任估计器都显示 0.5，收到同一份正面反馈后，一个变成约 0.667，另一个只变成约 0.549。它们没有出现计算冲突：显示值相同，内部积累的证据量不同。对需要重启后继续更新的系统，这意味着“保存分数”和“保存可恢复状态”是两件事。</p><p>这一反例来自本次对 TASMAN（多智能体信任与谈判研究系统）固定版本源码的内部实验。它回答的是状态与输入构造问题，没有执行模型谈判，也没有测量信任能否改善协议达成率。本文的判断是：估计器状态、向决策者展示的信息、使用信息的指导，应作为三个不同的设计与评估对象。[1][2]</p><h2 id="一个均值-两个不同的后续更新" tabindex="-1">一个均值，两个不同的后续更新 <a class="header-anchor" href="#一个均值-两个不同的后续更新" aria-label="Permalink to &quot;一个均值，两个不同的后续更新&quot;">​</a></h2><p>论文的 BRS（贝叶斯信誉估计方法）把正负证据累计为状态，再映射为信任分数。研究对象记录的机制是：模型报告事件，代码归一化反馈并执行更新。论文所说“只有信任分数跨局传递”，限定的是谈判模型获得的输入；估计器内部仍保存证据计数。不能据此推断整个系统没有历史状态。[1，第三节与信誉估计附录]</p><p>2026 年 10 月 26 日的内部实验调用固定提交中的原有函数，构造两组状态，使用相同的归一化正面反馈和 0.9 的衰减系数。[2]</p><table tabindex="0"><thead><tr><th>正负证据状态</th><th>更新前分数</th><th>更新后状态</th><th>更新后分数</th></tr></thead><tbody><tr><td>(0, 0)</td><td>0.5</td><td>(1, 0)</td><td>0.6666666667</td></tr><tr><td>(4, 4)</td><td>0.5</td><td>(4.6, 3.6)</td><td>0.5490196078</td></tr></tbody></table><p>表中是本次内部源码实验结果，不是作者的谈判效果数据，也不是跨团队独立复现。两组状态当前投影相同，后续响应却不同：只保存 0.5，无法判断应该恢复哪一组证据量。</p><p>我们的解释是，这个可见均值对继续更新而言丢失了必要信息。它并不意味着决策模型必须看到所有历史记录。系统可以保留完整估计状态，只向谈判端展示均值；关键是持久化边界不能与展示边界混淆。若任务只是重放冻结分数，根本不再更新，完整证据量也未必需要进入这条重放路径。</p><h2 id="分数不变-指导仍然可以改变" tabindex="-1">分数不变，指导仍然可以改变 <a class="header-anchor" href="#分数不变-指导仍然可以改变" aria-label="Permalink to &quot;分数不变，指导仍然可以改变&quot;">​</a></h2><p>本次另一个内部对照把展示值固定为 0.20，分别构造仅展示、要求考虑分数、给出语义说明及更具体指导的提示。数值没有改变，提示正文或系统提示发生变化。它隔离了输入构造上的区别，没有观察模型如何投票。[2]</p><p>这个区别解释了为什么“信任是否有用”不是单一处理变量。证据如何形成决定估计器状态；状态如何投影决定决策者看见什么；提示如何解释分数决定模型被要求怎样使用它。比较两种方法时，若这三处一起改变，就不能把全部差异归给某一种更新公式。</p><p>论文内部还比较了固定、随机与重放条件。重放既有分数可以约束信息轨迹，帮助检验使用指导的影响；它不等于完全隔离所有行为反馈。论文也说明，参数敏感性曲线是在固定信号与谈判行为下离线重算，不能写成换参数重新谈判所产生的收益。[1，第四节与敏感性分析附录]</p><h2 id="作者报告的收益有具体适用条件" tabindex="-1">作者报告的收益有具体适用条件 <a class="header-anchor" href="#作者报告的收益有具体适用条件" aria-label="Permalink to &quot;作者报告的收益有具体适用条件&quot;">​</a></h2><p>论文报告，在一个模型和“一名强硬谈判者、三名一般谈判者”的设定中，重放条件相对原分数条件的协议达成率增量，对三种信任方法分别为 30.5±6.8、28.0±10.4、16.5±12.4 个百分点，区间为配对的 95% 置信区间。这里对应的是论文的 grok-r（推理模型实验别名）条件；这些数值是作者报告，不是本次实验测得。[1，表 3]</p><p>作者对另一模型 gemini-r（另一推理模型实验别名）的部分角色组合未报告显著提升；两名强硬谈判者的重放差异区间也包含零。识别对手的准确程度并不能保证协议收益。固定和随机对照又提示，效果也不能简单归结为一段通用指导文字。应保留模型、角色组合与区间，而不能只摘取最高增量。</p><p>这也限定了本文的原创证据：源码反例支持“均值不足以恢复该估计器”，固定分数对照支持“指导可以独立改变输入”。两者都不支持“保存更多状态一定提高谈判成功率”。</p><h2 id="恢复需要保留什么-仍需检验什么" tabindex="-1">恢复需要保留什么，仍需检验什么 <a class="header-anchor" href="#恢复需要保留什么-仍需检验什么" aria-label="Permalink to &quot;恢复需要保留什么，仍需检验什么&quot;">​</a></h2><p>对需要继续学习的信任系统，我们建议把证据状态及更新规则版本作为恢复对象，并单独记录给决策者的投影与指导配置。这是从当前实现得到的工程解释，不是对所有信任模型的充分性定理。对于另一种估计器，哪些状态足以恢复，需要按其更新规则重新确认。</p><p>本次没有执行付费模型调用，没有重跑论文的完整谈判实验。当前仓库默认配置也不等于论文每个实验臂的冻结配置。多对手、适应性对手、身份变化及混合模型条件仍留有空缺。下一步需要在固定私有效用等条件下，分别改变状态恢复方式与使用指导，再测量协议及收益；本文不把这个待做实验写成既有结果。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>本文的“来源陈述”指论文作者报告的机制和结果，尚无本文核验的独立谈判实验；“内部实验依据”指本研究方于同日执行的固定源码函数探针；“研究解释”是从这些有限观察推导的设计判断。公开代码可核对实现，但公开身份、引用和发表状态不等于独立验证，函数正确执行也不意味着方法普遍有效。</p><ol><li>TASMAN 研究团队，研究论文，2026 年 10 月版本，第三至第五节、表 3、信誉估计与敏感性分析附录：<a href="https://arxiv.org/html/2610.31971" target="_blank" rel="noreferrer">论文全文</a>。机制、实验条件与收益均按作者报告处理。</li><li>TASMAN 项目维护者，公开源码，固定提交 <code>7e55fdb8791dd9ec03819534649420311ab8b374</code>：<a href="https://github.com/amit-sarker/TASMAN/blob/7e55fdb8791dd9ec03819534649420311ab8b374/src/BRS/brs.py" target="_blank" rel="noreferrer">信誉估计实现</a>。本地内部实验保留了源码哈希、输入、输出与提示对照；它没有测量模型行为。</li></ol><p>封面：基于本文状态投影问题创作的编辑插画；不作为实验结果图。</p>',24))])}const f=s(n,[["render",c]]);export{g as __pageData,f as default};
